<template>
  <div class="max-width-120 images-list">
    <div class="full-width bg-white q-ma-sm scroll-area-height">
      <div class="row justify-center q-pl-md q-pr-md q-pt-md">
        <span class="secondary-c-text text-h6 text-weight-bold">
          {{ $t('page_number_text') }}
        </span>
      </div>
      <div class="q-pl-md q-pr-md full-width left-scroll-area-height scrolle-y">
        <img
          v-for="(imageMoc, index) in images"
          :data-id="index"
          :key="index"
          :src="baseUrl + '/' + imageMoc.path + '?' + tokenQueryParam"
          class="q-pa-sm shadow-5 full-width q-ma-sm cursor-pointer"
          :class="index === page - 1 ? 'active' : ''"
          style="height: auto"
          @click="imageclicked"
          @load="
            (evt) => {
              imageLoaded(evt, Number(index));
            }
          "
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { useImageAuth } from 'src/composables/useImageAuth';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import documentUtil from 'src/utils/documentUtil';
import { cleanUpImagesUrl } from 'src/utils/viewImages';
import {
  useDocumentStore,
  useDocTableSelectionStore} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [documentUtil],
  components: {},
  props: {},
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    imageLoaded(event: any, index: number) {
      this.image_load_count++;
      if (this.image_load_count > this.images.length) {
        this.image_load_count = this.images.length;
      }

      if (this.image_load_count === this.images.length) {
        this.processing = false;
      }
    },

    initView() {
      if (!this.doc_loaded) {
        return;
      }

      this.processing = true;
      this.image_load_count = 0;
      this.images = cleanUpImagesUrl(this.record.images);
    },

    imageclicked(evt: any) {
      this.page = parseInt(evt.target.dataset.id) + 1;
      this.setImage(this.record);
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, doc_loaded } = storeToRefs(doc_store);

    const table_selection = useDocTableSelectionStore();
    const { page, baseUrl } = storeToRefs(table_selection);
    const { setImage } = table_selection;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    return {
      tokenQueryParam,
      record,
      doc_loaded,
      images: ref([] as any),
      processing: ref(false),
      baseUrl,
      image_load_count: ref(0),
      page,
      setImage,
    };
  },
});
</script>

<style scoped>
.images-list {
  margin-left: 10px !important;
  margin-right: 10px !important;
}
.scroll-area-height {
  min-height: 200px;
}
</style>
