<!--vbase-->
<template>
  <!-- Add Components -->

  <div class="row full-width q-ma-sm">
    <div class="col-auto">
      <ImagesList />
    </div>
    <div class="col" style="margin-right: 10px">
      <div
        class="full-width bg-white"
        id="image_container"
        ref="image_container"
      >
        <div
          class="full-width full-height scrolle-y"
          id="image_scrolle"
          style="position: relative"
        >
          <div
            id="zoom"
            :style="
              'background-image: url(&quot;' +
              image +
              ' &quot;); top: 51px;left: 506px; background-position: 268.297px 82.6934px;'
            "
          ></div>

          <img
            class="screenshot"
            :data-page="page"
            :src="image"
            :width="imageWidth"
            id="screenshot"
            ref="screenshot"
            draggable="false"
            @load="getImageDetails"
          />
          <AddColumnSplitterBtn />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useDocumentStore, useDocTableSelectionStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { ApiExceptions } from 'src/exceptions/index';

import ImagesList from '../components/TableSelection/ImagesList.vue';
import AddColumnSplitterBtn from '../components/TableSelection/AddColumnSplitterBtn.vue';
export default defineComponent({
    components: {
    ImagesList,
    AddColumnSplitterBtn,
  },
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
    image: {
      handler: function (newVal, oldVal) {
        this.calculateImage();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
  },

  data() {
    return {};
  },
  methods: {
    initView() {
      if (!this.doc_loaded) {
        return;
      }
      window.addEventListener('resize', this.windowResize);
      this.image_container = this.$refs.image_container as HTMLElement;
      this.setImage(this.record);
    },

    calculateImage() {
      if (!this.image_container) {
        return;
      }

      this.imageWidth = this.image_container.offsetWidth - 30;
      this.imageHeight = this.image_container.offsetHeight;
    },

    getImageDetails() {
      const screenshot = this.$refs.screenshot as HTMLElement;
      this.imageInfo = {
        offsetWidth: screenshot.offsetWidth,
        offsetHeight: screenshot.offsetHeight,
      };
    },

    windowResize() {
      this.calculateImage();
    },
  },

  setup() {
    const doc_store = useDocumentStore();
    const { record, doc_loaded } = storeToRefs(doc_store);

    const table_selection = useDocTableSelectionStore();
    const {
      page,
      baseUrl,
      image,
      imageWidth,
      imageHeight,
      image_container,
      imageInfo,
    } = storeToRefs(table_selection);
    const { setImage } = table_selection;
    return {
      record,
      doc_loaded,
      imageInfo,
      setImage,
      image,
      page,
      baseUrl,
      imageWidth,
      imageHeight,
      image_container,
    };
  },
});
</script>

<style lang="scss" scoped>
#image_container {
  height: calc(100vh - 230px) !important;
}
</style>
