<template>
  <div
    class="button-add-column-splitter"
    onclick="addColumnSplitter();"
    data-toggle="tooltip"
    data-placement="right"
  >
    <q-icon name="add" style="position: absolute; top: 41%; right: 3px" size="xs" />
    <q-tooltip>Add Column</q-tooltip>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useDocumentStore, useDocTableSelectionStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import documentUtil from 'src/utils/documentUtil';

export default defineComponent({
  el: '#app',
  mixins: [documentUtil],
  components: {},
  props: {},
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    initView() {
      if (!this.doc_loaded) {
        return;
      }
    },

    addColumnSplitter(evt: any) {
      logInfo(evt);
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, doc_loaded } = storeToRefs(doc_store);

    const table_selection = useDocTableSelectionStore();
    const { page } = storeToRefs(table_selection);
    const { setImage } = table_selection;
    return {};
  },
});
</script>

