<!--vbase-->
<template>
  <DocumentLock
    :document_version="document_version"
    :trigger_document_lock="trigger_document_lock"
  />
  <PageTop />

  <!-- Add Components -->

  <template v-if="view == 'table_selection'">
    <TableSelection />
  </template>

  <!-- Add Components -->

  <q-inner-loading :showing="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { useDocumentStore, useDocTableTrainingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import DocumentLock from 'src/components/DocumentLock.vue';
import PageTop from './components/PageTop.vue';
import TableSelection from './pages/TableSelection.vue';
export default defineComponent({
    el: '#app',
  components: {
    DocumentLock,
    PageTop,
    TableSelection,
  },
  watch: {
    doc_processing: {
      handler: function (newVal, oldVal) {
        this.handleLoader(newVal);
      },
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { getDocumentById } = doc_store;
    const { processing: doc_processing, document_version } =
      storeToRefs(doc_store);

    const doc_table_training = useDocTableTrainingStore();
    const { doc_id, processing, view } = storeToRefs(doc_table_training);
    const { handleLoader } = doc_table_training;
    return {
      getDocumentById,
      handleLoader,
      doc_id,
      doc_processing,
      processing,
      document_version,
      trigger_document_lock: ref(false),
      view,
    };
  },
  data() {
    return {};
  },
  mounted() {
    this.init();
  },

  methods: {
    async init() {
      try {
        this.doc_id = this.$route.params.id as string;
        await this.getDocumentById(this.doc_id);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
  },
});
</script>

<style lang="scss" scoped></style>
